def audit_binding(conn,parameters,scan_budget):
    samples=[]
    with conn.cursor() as c:
        c.execute('CREATE SESSION BINDING FOR SELECT payload FROM skew WHERE k=1 USING SELECT /*+ USE_INDEX(skew,idx_k) */ payload FROM skew WHERE k=1')
        try:
            for parameter in parameters:
                c.execute('EXPLAIN ANALYZE SELECT payload FROM skew WHERE k=%s',(parameter,))
                plan=c.fetchall()
                c.execute('SELECT @@last_plan_from_binding')
                used=c.fetchone()[0]
                scans=[int(r[2]) for r in plan if 'TableRowIDScan' in r[0] or 'IndexRangeScan' in r[0]]
                if not scans:raise RuntimeError('Expected index lookup scan operators')
                samples.append({'parameter':parameter,'scan_rows':max(scans),'used_binding':used,'plan':list(plan)})
            kept=all(s['scan_rows']<=scan_budget for s in samples)
        except Exception:
            c.execute('DROP SESSION BINDING FOR SELECT payload FROM skew WHERE k=1')
            raise
        if not kept:c.execute('DROP SESSION BINDING FOR SELECT payload FROM skew WHERE k=1')
    return {'kept':kept,'samples':samples}
